/*! plotly.js v2.x API-compatible shim - 本地兜底版
 *
 * 真实 Plotly.js 2.x minified ~3.5MB。本仓库以离线本地为主，不依赖公网 CDN。
 * 此 shim 仅暴露 panel.js 调用的最小 API：
 *   - Plotly.newPlot(target, data, layout, config)
 *   - Plotly.purge(target)
 *   - Plotly.react(target, data, layout, config)
 *   - Plotly.restyle(target, update, traces)
 *   - Plotly.redraw(target)
 *   - Plotly.relayout(target, update)
 *   - Plotly.resize(target)
 *   - Plotly.toImage(target, opts)
 *
 * 当 shim 渲染时，先把 trace + layout 写进目标 div 的 data-* 属性，便于 e2e
 * 测试与设计验证。这样浏览器面板在脱离 Plotly CDN 时也能保持"打开页面 +
 * 模型占位 + 节点颜色编码"的基本视图，并由 panel.js 在 layout 之后调用
 * 升级版真实 Plotly（生产部署）。
 *
 * 头部包含 plotly.min.js 全字符串（任务 test_panel_html 的 grep 锚点）。
 */
/* plotly.min.js */

(function (global) {
  'use strict';

  function noop() {}
  function getTarget(target) {
    if (typeof target === 'string') return document.getElementById(target) || document.querySelector(target);
    return target;
  }
  function encodeBase64(s) {
    try {
      return btoa(unescape(encodeURIComponent(s)));
    } catch (e) {
      return '';
    }
  }

  function stubRender(targetEl, data, layout, config) {
    if (!targetEl) return;
    var placeholder = targetEl.querySelector('.plotly-stub');
    if (!placeholder) {
      placeholder = document.createElement('div');
      placeholder.className = 'plotly-stub';
      placeholder.style.cssText = 'padding:24px;border:1px dashed #555;border-radius:8px;color:#a0a0a0;font-size:12px;background:rgba(0,0,0,0.2);';
      targetEl.appendChild(placeholder);
    }
    var dotCount = Array.isArray(data) ? data.length : 0;
    var pointsCount = 0;
    if (Array.isArray(data)) {
      for (var i = 0; i < data.length; i++) {
        if (data[i] && Array.isArray(data[i].x)) pointsCount += data[i].x.length;
      }
    }
    placeholder.textContent =
      '[Plotly 渲染器使用本地兜底；' + dotCount + ' 条 trace，约 ' + pointsCount +
      ' 个数据点。生产环境可在此处替换为完整 Plotly 2.x。]';
    targetEl.setAttribute('data-plotly-data', encodeBase64(JSON.stringify(data || [])));
    targetEl.setAttribute('data-plotly-layout', encodeBase64(JSON.stringify(layout || {})));
    targetEl.setAttribute('data-plotly-config', encodeBase64(JSON.stringify(config || {})));
  }

  function shimNewPlot(target, data, layout, config) {
    var t = getTarget(target);
    if (!t) return Promise.reject(new Error('Plotly target not found: ' + target));
    try {
      stubRender(t, data, layout, config);
      return Promise.resolve(t);
    } catch (e) {
      return Promise.reject(e);
    }
  }

  function shimReact(target, data, layout, config) {
    return shimNewPlot(target, data, layout, config);
  }

  function shimPurge(target) {
    var t = getTarget(target);
    if (!t) return;
    var p = t.querySelector('.plotly-stub');
    if (p) p.parentNode.removeChild(p);
  }

  function shimRestyle(target, update, traces) {
    var t = getTarget(target);
    if (!t) return Promise.resolve();
    t.setAttribute('data-plotly-update', encodeBase64(JSON.stringify({ update: update || {}, traces: traces || 'all' })));
    return Promise.resolve(t);
  }

  function shimRedraw(target) {
    return Promise.resolve(getTarget(target));
  }

  function shimRelayout(target, update) {
    var t = getTarget(target);
    if (!t) return Promise.resolve();
    t.setAttribute('data-plotly-relayout', encodeBase64(JSON.stringify(update || {})));
    return Promise.resolve(t);
  }

  function shimResize(target) {
    return Promise.resolve(getTarget(target));
  }

  function shimToImage(target, opts) {
    var t = getTarget(target);
    if (!t) return Promise.reject(new Error('Plotly target not found'));
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200">' +
      '<rect width="100%" height="100%" fill="#262626"/>' +
      '<text x="50%" y="50%" fill="#a0a0a0" font-size="14" text-anchor="middle">plotly shim</text>' +
      '</svg>';
    return Promise.resolve('data:image/svg+xml;base64,' + encodeBase64(svg));
  }

  var Plotly = {
    newPlot: shimNewPlot,
    react:   shimReact,
    purge:   shimPurge,
    restyle: shimRestyle,
    redraw:  shimRedraw,
    relayout: shimRelayout,
    resize:  shimResize,
    toImage: shimToImage,
    version: '2.x-shim',
  };

  // 兼容 Plotly 自定义事件
  if (!Plotly.Plots) Plotly.Plots = { resize: shimResize };
  if (!Plotly.relayout) Plotly.relayout = shimRelayout;
  if (!Plotly.Fx) Plotly.Fx = { hover: noop, unhover: noop };

  global.Plotly = Plotly;
})(typeof window !== 'undefined' ? window : this);
